CREATE procedure SP_MM_ConsultaIdTareaPorPedido	@IdSolicitudPedido INT,	@Version INT,	/*--------------------parametros contrato  --------------------*/    @IdContrato    INT = null,    @IdUsuario     INT = null,    @FechaRegistro DATETIME = null	/*-------------------------------------------------------------*/ASBEGIN	SELECT t.IdTarea	FROM dbo.MM_SolicitudPedido sp	INNER JOIN dbo.TA_Operacion o ON o.IdDocumento = sp.IdSolicitudPedido AND o.NoVersion = @Version	INNER JOIN dbo.TA_Tarea t ON t.IdOperacion = o.IdOperacion	WHERE sp.IdSolicitudPedido = @IdSolicitudPedido		AND o.IdTipoOperacion = 9END